// A scene names its case by id; resolve it from the bank (an unknown id fails at load).
for (const s of SCENES) if (typeof s.case === "string") {
  if (!CASES[s.case]) throw new Error(`${s.id}: unknown case ${s.case}`);
  s.case = { id: s.case, ...CASES[s.case] };
}
export const SCENE = Object.fromEntries(SCENES.map((s) => [s.id, s]));
export const POLL_TYPES = new Set(["poll", "gantt", "fork"]);
